def M(t,pairs,hint='أَرْسُمُ خَطًّا مِنَ الصُّورَةِ إِلَى الكَلِمَةِ ✏️'):
  n=len(pairs); r=[pairs[(k+2)%n][1] for k in range(n)]
  return {"type":"match","title":t,"hint":hint,"rows":[[p[0],"","="+r[k]] for k,p in enumerate(pairs)]}
def C(t,rows,hint='أَضَعُ دَائِرَةً حَوْلَ الصُّورَةِ الصَّحِيحَةِ ⭕'): return {"type":"circle","title":t,"hint":hint,"rows":rows}
def TF(t,top,rows): return {"type":"tf","title":t,"top":top,"rows":rows,"hint":"أَضَعُ ✓ لِلصَّوَابِ، وَ ✗ لِلْخَطَأِ"}
def CT(t,rows,hint='أَعُدُّ، وَأَكْتُبُ العَدَدَ فِي الدَّائِرَةِ 🔢'): return {"type":"count","title":t,"rows":rows,"hint":hint}
def WD(t,rows,hint=HW): return {"type":"words","title":t,"hint":hint,"rows":rows}
def DR(t,hint,label): return {"type":"draw","title":t,"hint":hint,"label":label}
def MZ(t,a,b,seed): return {"type":"maze","title":t,"from":a,"to":b,"seed":seed}
def REF(t,txt,src,arts): return {"type":"raw","title":t,"html":f'<div class="refc" style="--h:45;margin-top:40px"><p>{txt}</p><span>📖 {src}</span></div>',"arts":arts}
